 private static int stage,frames,checks;private static long started;private static UUID parent;private static VehicleScan scan;private static BlockPos localArm,nativeHead;private static double releasePhase;private static int owned;private static Vec3d aimFeet;private static boolean done,submitted;private static String transferError;
 private static WorldServer world(Minecraft mc){return mc.getIntegratedServer().getWorld(0);}private static EntityPlayerMP actor(Minecraft mc){return mc.getIntegratedServer().getPlayerList().getPlayers().get(0);}private static EntityGroundVehicle craft(Minecraft mc){return parent==null?null:(EntityGroundVehicle)world(mc).getEntityFromUuid(parent);}
 private static void need(boolean v,String why){checks++;if(!v)throw new IllegalStateException("Captured-arm release: "+why+" stage="+stage+" frames="+frames);}
 private static int owned(EntityGroundVehicle craft){int n=craft.structure.cells.size();for(net.minecraft.tileentity.TileEntity tile:craft.view.tiles.values())if(tile instanceof GearTileEntity){GearTileEntity arm=(GearTileEntity)tile;if(arm.payload()!=null&&!arm.payload().materialized())n+=arm.payload().blocks.cells.size();}return n;}
 private static List<EntityGroundVehicle> outputs(WorldServer world){List<EntityGroundVehicle> out=new ArrayList<>();for(Entity e:world.loadedEntityList)if(e instanceof EntityGroundVehicle&&!e.isDead){EntityGroundVehicle c=(EntityGroundVehicle)e;if(c.structure!=null&&c.posX>1850&&c.posX<1950&&c.posZ>1850&&c.posZ<1950)out.add(c);}return out;}
 private static void setup(Minecraft mc){WorldServer world=world(mc);EntityPlayerMP player=actor(mc);VehicleArmCouplerFixture.setup(world,player);BlockPos base=VehicleArmCouplerFixture.BASE;world.setBlockState(base.add(0,2,6),ModBlocks.VEHICLE_CONTROLLER.getDefaultState(),2);BlockPos seat=base.add(1,2,6);world.setBlockState(seat,ModBlocks.PILOT_SEAT.getDefaultState(),2);ModBlocks.PILOT_SEAT.onBlockPlacedBy(world,seat,world.getBlockState(seat),player,new ItemStack(ModBlocks.PILOT_SEAT));world.setBlockState(base.add(2,2,8),Block.getBlockFromName("vandorlabs:impulse_engine").getDefaultState(),2);for(int section=0;section<2;section++){BlockPos at=base.add(2,2,section==0?0:9);world.setBlockState(at,Blocks.CHEST.getDefaultState(),2);TileEntityChest chest=(TileEntityChest)world.getTileEntity(at);chest.setInventorySlotContents(0,new ItemStack(Items.DIAMOND,section==0?7:11));chest.setCustomName("Arm release section "+section);}scan=new VehicleScan(world,base.add(VehicleArmCouplerFixture.SEAT));}
 private static void receipt(EntityGroundVehicle craft){if(!VehicleArmCouplers.runtime())return;UUID generation=craft.couplerAssociationGeneration();need(generation!=null&&craft.couplerScopeReady(),"accepted split has installed external receipt");VehicleArmCouplers.Snapshot observed=VehicleArmCouplers.observe(craft);need(!observed.heads.isEmpty(),"split retains actual released head");for(VehicleArmCouplers.Head head:observed.heads)need(head.released&&head.association!=null&&head.association.permitsUnpaired(head.association.head,craft.getUniqueID(),generation),"all retained native/captured heads rekey to output owner/generation");need(VehicleArmCouplerPairs.discoverForParking(observed).pairs.isEmpty(),"scoped split does not rejoin coincident released heads");}
 private static boolean capturedClick(){return "1".equals(System.getenv("VANDOR_LABS_COUPLER_ARM_RELEASE_CAPTURED_ONLY"));}
 private static VehicleArmCouplers.Address capturedAddress(EntityGroundVehicle c){GearTileEntity a=(GearTileEntity)c.view.getTileEntity(localArm);if(a==null||a.payload()==null)return null;for(VehicleStructure.Cell cell:a.payload().blocks.cells)if(cell.state.getBlock() instanceof com.vandorlabs.coupler.BlockCoupler)return VehicleArmCouplers.Address.payloadCell(localArm,cell.pos);return null;}
 private static boolean intended(VehicleInteraction.Target hit,EntityGroundVehicle c,boolean release){if(hit==null||hit.craft!=c||hit.hit.action!=VehicleSelection.Action.COUPLER)return false;return release&&capturedClick()?Objects.equals(hit.hit.capturedCoupler,capturedAddress(c)):hit.hit.capturedCoupler==null&&hit.hit.cell.pos.equals(nativeHead);}
